import faulthandler, os, sys, json, subprocess, hashlib, glob
faulthandler.dump_traceback_later(60, exit=True)
sys.stdin = open(os.devnull)
sys.path.insert(0, 'benchmark/scripts')
sys.argv = ['score.py']
import score

def sha(b):
    return hashlib.sha256(b).hexdigest()

def head(p):
    return subprocess.run(['git', 'show', 'HEAD:' + p], capture_output=True, check=True).stdout

TRACK = ['benchmark/scripts/score.py', 'benchmark/challenges/library-icon-tests.json',
         'benchmark/challenges/library-specialty.json', 'benchmark/results/challenges.json']
print('main rc', score.main())
jsons = [p for p in glob.glob('benchmark/**/*.json', recursive=True)]
changed = set()
for rnd in range(5):
    pairs = []
    for p in TRACK + sorted(changed - set(TRACK)):
        try:
            o = sha(head(p))
        except subprocess.CalledProcessError:
            continue
        n = sha(open(p, 'rb').read())
        if o != n:
            pairs.append((p, o, n))
    new_change = False
    for jp in jsons:
        if jp == 'benchmark/results/challenges.json':
            continue
        t = open(jp, encoding='utf-8', newline='').read()
        t2 = t
        for p, o, n in pairs:
            if o in t2:
                print('repin', jp, p, t2.count(o))
                t2 = t2.replace(o, n)
        if t2 != t:
            open(jp, 'w', encoding='utf-8', newline='').write(t2)
            changed.add(jp)
            new_change = True
    if not new_change:
        break
print('files repinned', sorted(changed))
for p in TRACK + sorted(changed - set(TRACK)):
    print(sha(open(p, 'rb').read()), p)
allp = {}
for p in TRACK + sorted(changed):
    try:
        allp[p] = sha(head(p))
    except subprocess.CalledProcessError:
        pass
for jp in jsons:
    t = open(jp, encoding='utf-8').read()
    for p, o in allp.items():
        if o in t and o != sha(open(p, 'rb').read()):
            print('STALE', jp, p)
